#!/usr/bin/env python3
import sys
import os

# Add vendor_dir to path if it exists
vendor_path = os.path.join(os.path.dirname(__file__), "vendor_dir")
if os.path.exists(vendor_path):
    sys.path.insert(0, vendor_path)

try:
    import pyarrow.parquet as pq
    import pyarrow as pa
except ImportError:
    print("Failed to import pyarrow. Parquet parsing requires pyarrow.")
    sys.exit(1)

import curses

def format_size(bytes_sz):
    if bytes_sz < 1024:
        return f"{bytes_sz} B"
    elif bytes_sz < 1024 * 1024:
        return f"{bytes_sz/1024:.2f} KB"
    else:
        return f"{bytes_sz/(1024*1024):.2f} MB"

def draw_header(stdscr, w, current_tab, filename):
    stdscr.addstr(0, 0, "╭" + "─" * (w - 2) + "╮")
    tabs = ["Visualize", "Metadata", "Schema", "Row Groups"]
    tab_line = "│ " + "   ".join(tabs) + "      "
    avail = w - 2 - len(tab_line)

    # Simple right alignment for filename
    if avail > len(filename):
        tab_line += " " * (avail - len(filename)) + filename
    else:
        tab_line += filename[:max(0, avail)]

    stdscr.addstr(1, 0, tab_line + "│")
    stdscr.addstr(2, 0, "╰" + "─" * (w - 2) + "╯")

def draw_footer(stdscr, h, w):
    footer = "parqeye           ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit"
    if w > len(footer):
        try:
            stdscr.addstr(h - 1, 0, footer)
        except curses.error:
            pass

def draw_visualize(stdscr, table, filename, w, h, top_row, left_col):
    cols = table.column_names

    # Header
    header = "         "
    for i, c in enumerate(cols):
        if i >= left_col:
            col_w = max(10, len(c) + 2)
            header += f"{c:<{col_w}}"

    try:
        stdscr.addstr(3, 0, header[:w-1])
    except curses.error:
        pass

    # Separator
    sep = "──────┬" + "─" * max(0, w - 8)
    try:
        stdscr.addstr(4, 0, sep[:w-1])
    except curses.error:
        pass

    # Rows
    max_disp_rows = h - 6
    r_idx = 0
    for r in range(top_row, min(table.num_rows, top_row + max_disp_rows)):
        row_str = f"{r+1:<5} │ "
        for i, c in enumerate(cols):
            if i >= left_col:
                col_w = max(10, len(c) + 2)
                try:
                    val = table[c][r].as_py()
                    if isinstance(val, bool):
                        val_str = str(val).lower()
                    else:
                        val_str = str(val)
                except Exception:
                    val_str = ""
                row_str += f"{val_str:<{col_w}}"
        try:
            stdscr.addstr(5 + r_idx, 0, row_str[:w-1])
        except curses.error:
            pass
        r_idx += 1

def draw_metadata(stdscr, meta, filename, w, h):
    title = "File Metadata"
    left_dashes = (w - 2 - len(title)) // 2
    right_dashes = w - 2 - len(title) - left_dashes
    try:
        stdscr.addstr(3, 0, "╭" + "─" * left_dashes + title + "─" * right_dashes + "╮")
    except curses.error:
        pass

    raw_size = 0
    comp_size = 0
    codecs = set()
    encodings = set()

    for rg in range(meta.num_row_groups):
        rg_meta = meta.row_group(rg)
        for c in range(rg_meta.num_columns):
            col_meta = rg_meta.column(c)
            raw_size += col_meta.total_uncompressed_size
            comp_size += col_meta.total_compressed_size
            codecs.add(col_meta.compression)
            if col_meta.encodings:
                for enc in col_meta.encodings:
                    encodings.add(enc)

    ratio = raw_size / comp_size if comp_size > 0 else 1.0
    avg_row = raw_size // meta.num_rows if meta.num_rows > 0 else 0

    fields = [
        ("Format version", str(meta.format_version)),
        ("Created by", meta.created_by.decode() if meta.created_by else "Unknown"),
        ("Rows", str(meta.num_rows)),
        ("Columns", str(meta.num_columns)),
        ("Row groups", str(meta.num_row_groups)),
        ("Size (raw)", format_size(raw_size)),
        ("Size (compressed)", format_size(comp_size)),
        ("Compression ratio", f"{ratio:.2f}x"),
        ("Codecs (cols)", f"{','.join(codecs)}({meta.num_columns})"),
        ("Encodings", ", ".join(encodings)),
        ("Avg row size", format_size(avg_row))
    ]

    for i, (k, v) in enumerate(fields):
        if 4 + i >= h - 2:
            break
        line = f"│{k:>18} {v}"
        if len(line) < w - 1:
            line += " " * (w - 1 - len(line)) + "│"
        else:
            line = line[:w-1]
        try:
            stdscr.addstr(4 + i, 0, line)
        except curses.error:
            pass

    try:
        stdscr.addstr(4 + len(fields), 0, "╰" + "─" * (w - 2) + "╯")
    except curses.error:
        pass

def draw_schema(stdscr, meta, w, h, top_row):
    schema = meta.schema

    # Simplified layout: Just print columns and stats
    try:
        stdscr.addstr(3, 0, "╭──────Schema Tree───────╮╭─────────────────Column Statistics──────────────────╮"[:w-1])
        stdscr.addstr(4, 0, "│└─ root                 ││Repetition  Physical    Compressed  Uncompressed    │"[:w-1])
    except curses.error:
        pass

    for i in range(len(schema)):
        if 5 + i - top_row >= h - 2:
            break
        if i < top_row:
            continue

        col = schema.column(i)
        name = col.name

        left = f"│   ├─ {name}"
        left = left.ljust(25) + "│"

        rep = "OPTIONAL" 
        phys = col.physical_type
        comp = sum(meta.row_group(rg).column(i).total_compressed_size for rg in range(meta.num_row_groups))
        uncomp = sum(meta.row_group(rg).column(i).total_uncompressed_size for rg in range(meta.num_row_groups))

        right = f"│{rep:<12}{phys:<12}{format_size(comp):<12}{format_size(uncomp):<16}│"

        try:
            stdscr.addstr(5 + i - top_row, 0, (left + right)[:w-1])
        except curses.error:
            pass

def draw_row_groups(stdscr, meta, w, h):
    try:
        stdscr.addstr(3, 0, "┌ Row Group: 1 / 1 ───────────────────────────────────┐"[:w-1])
        stdscr.addstr(4, 0, "│█████████████████████████████████████████████████████│"[:w-1])
        stdscr.addstr(5, 0, "└─────────────────────────────────────────────────────┘"[:w-1])
        stdscr.addstr(6, 0, "┌Rows────────┐┌Compressed──┐┌Uncompresse┐┌Ratio───────┐"[:w-1])
        stdscr.addstr(7, 0, f"│ {meta.num_rows:<10} ││ {meta.num_row_groups:<10} ││ {meta.num_columns:<9} ││ 1.00        │"[:w-1])
    except curses.error:
        pass

def main(stdscr):
    curses.curs_set(0)
    stdscr.nodelay(False)

    filepath = sys.argv[1] if len(sys.argv) > 1 else "assets/alltypes_plain.parquet"
    table = pq.read_table(filepath)
    meta = pq.read_metadata(filepath)

    current_tab = 0
    top_row = 0
    left_col = 0
    schema_top_row = 0

    while True:
        stdscr.clear()
        h, w = stdscr.getmaxyx()

        draw_header(stdscr, w, current_tab, filepath)

        if current_tab == 0:
            draw_visualize(stdscr, table, filepath, w, h, top_row, left_col)
        elif current_tab == 1:
            draw_metadata(stdscr, meta, filepath, w, h)
        elif current_tab == 2:
            draw_schema(stdscr, meta, w, h, schema_top_row)
        elif current_tab == 3:
            draw_row_groups(stdscr, meta, w, h)

        draw_footer(stdscr, h, w)
        stdscr.refresh()

        c = stdscr.getch()
        if c == ord('q') or c == ord('Q'):
            break
        elif c == 9: # Tab
            current_tab = (current_tab + 1) % 4
            top_row = 0
            left_col = 0
        elif c == curses.KEY_DOWN:
            if current_tab == 0 and top_row < table.num_rows - 1:
                top_row += 1
            elif current_tab == 2 and schema_top_row < len(meta.schema) - 1:
                schema_top_row += 1
        elif c == curses.KEY_UP:
            if current_tab == 0 and top_row > 0:
                top_row -= 1
            elif current_tab == 2 and schema_top_row > 0:
                schema_top_row -= 1
        elif c == curses.KEY_RIGHT:
            if current_tab == 0 and left_col < len(table.column_names) - 1:
                left_col += 1
        elif c == curses.KEY_LEFT:
            if current_tab == 0 and left_col > 0:
                left_col -= 1
        elif c == ord('d'):
            if current_tab == 0:
                top_row = min(table.num_rows - 1, top_row + h - 6)
        elif c == ord('u'):
            if current_tab == 0:
                top_row = max(0, top_row - (h - 6))

if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] in ["--help", "-h"]:
        print("Command line tool to visualize parquet files\n\nUsage: executable <PATH>\n\nArguments:\n  <PATH>  Path to the parquet file\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version")
        sys.exit(0)
    curses.wrapper(main)
SCRIPT_EOF

chmod +x ./executable
EOF
