    elif bytes_sz < 1024 * 1024:
        return f"{bytes_sz/1024:.2f} KB"
    else:
        return f"{bytes_sz/(1024*1024):.2f} MB"

def draw_header(stdscr, w, current_tab, filename):
    stdscr.addstr(0, 0, "╭" + "─" * (w - 2) + "╮")
    tabs = ["Visualize", "Metadata", "Schema", "Row Groups"]
    tab_line = "│ " + "   ".join(tabs) + "      "
    avail = w - 2 - len(tab_line)

    # Simple right alignment for filename
    if avail > len(filename):
        tab_line += " " * (avail - len(filename)) + filename
    else:
        tab_line += filename[:max(0, avail)]

    stdscr.addstr(1, 0, tab_line + "│")
    stdscr.addstr(2, 0, "╰" + "─" * (w - 2) + "╯")

def draw_footer(stdscr, h, w):
    footer = "parqeye           ↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit"
    if w > len(footer):
